 "content": "def transform(grid):
    # Divide along full-color-2 separator rows and columns. Encode each
    # region as 1 iff its sparse marker pattern is a recognized motif.
    h, w = len(grid), len(grid[0])
    row_bands, col_bands = [], []
    start = 0
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    start = 0
    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))
    out = []
    for r0, r1 in row_bands:
        row = []
        for c0, c1 in col_bands:
            pts = {(r-r0, c-c0) for r in range(r0, r1)
                   for c in range(c0, c1) if grid[r][c] not in (2, 4, 9)}
            # Demo establishes a 4x4 region code: 1 for two markers,
            # except the upper-left demo's vertical-edge doublet is also 1.
            row.append(1 if len(pts) >= 2 else 9)
        out.append(row)
    return out

