 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find uniform separator rows/columns, keeping their palette value.
    row_cuts = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            row_cuts.append((r, grid[r][0]))
    col_cuts = []
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            col_cuts.append((c, next(iter(vals))))

    def ranges(length, cuts):
        out, start = [], 0
        for i, _ in cuts:
            if start < i:
                out.append((start, i))
            start = i + 1
        if start < length:
            out.append((start, length))
        return out

    rbands, cbands = ranges(h, row_cuts), ranges(w, col_cuts)
    output = []
    for r0, r1 in rbands:
        outrow = []
        for c0, c1 in cbands:
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            divider_colors = {v for _, v in row_cuts + col_cuts}
            counts = Counter(v for v in vals if v not in divider_colors)
            background = counts.most_common(1)[0][0]
            marker_count = sum(n for color, n in counts.items() if color != background)
            outrow.append(1 if marker_count >= 2 else background)
        output.append(outrow)
    return output

